const $=s=>document.querySelector(s),money=n=>'₹'+n.toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
const configs=[{name:'EMI & repayments',intro:'Home, car, personal or education loans.',fields:[['p','Loan amount (₹)',500000],['r','Annual interest (%)',10],['n','Term (months)',60],['x','Extra monthly payment (₹)',0]]},{name:'Compare loans',intro:'Compare the same amount with different rates, terms and upfront fees.',fields:[['p','Loan amount (₹)',500000],['a','Loan A rate (%)',10],['b','Loan B rate (%)',9],['na','Loan A months',60],['nb','Loan B months',60],['fa','Loan A fee (₹)',0],['fb','Loan B fee (₹)',5000]]},{name:'Flat / interest only',intro:'Interest calculated on the original principal throughout the term.',fields:[['p','Principal (₹)',100000],['r','Annual interest (%)',12],['n','Term (months)',12]]},{name:'Chit fund',intro:'Enter the discount in rupees and commission as a percentage of the chit face value. Commission is included in the discount.',fields:[['p','Chit face value (₹)',100000],['n','Members / installments',20],['d','Auction discount (₹)',25000],['c','Organizer commission (%)',5]]}];
configs.push({name:'Chit Planner',intro:'Compare the payout you receive, everything you pay over 20 months, and interest earned by lending the payout outside.',fields:[['p','Chit face value (₹)',4000000],['paid','Total you pay over 20 months (₹)',4000000],['external','Outside lending interest — annual (%)',12],['commission','Organizer commission (%)',4],['take','Payout month',1]]});
let mode=0,schedule=[],lastResult={};
function payment(p,r,n){let rate=r/1200;return rate?p*rate/-Math.expm1(-n*Math.log1p(rate)):p/n}
function amort(p,r,n,x=0){let e=payment(p,r,n),bal=p,rows=[];for(let i=1;i<=n;i++){let interest=bal*r/1200,paid=Math.min(e+x,bal+interest);if(i===n)paid=bal+interest;let principal=paid-interest;bal=Math.max(0,bal-principal);rows.push([i,paid,principal,interest,bal]);if(bal<1e-8)break}return rows}
function read(){let v={};for(let [key,label] of configs[mode].fields){let el=$('#f-'+key),raw=el.value.trim(),n=Number(raw);if(!raw||!Number.isFinite(n)||n<0||n>1e12)throw Error(label+': enter a valid nonnegative number (up to 1 trillion).');if(['p','n','na','nb'].includes(key)&&n<=0)throw Error(label+' must be greater than zero.');if(['n','na','nb'].includes(key)&&(!Number.isInteger(n)||n>1200))throw Error(label+': use a whole number from 1 to 1200.');v[key]=n}if(mode===3&&!(v.c<=100&&v.p*v.c/100<=v.d&&v.d<=v.p))throw Error('Commission must be 0–100% of face value. Its rupee amount cannot exceed the discount, and the discount cannot exceed face value.');return v}
function calculate(){if(mode===4)return calculatePlanner();try{const v=read();let hero,label,metrics,note='',ratio=null;schedule=[];if(mode===0){schedule=amort(v.p,v.r,v.n,v.x);let interest=schedule.reduce((s,r)=>s+r[3],0),baseline=amort(v.p,v.r,v.n).reduce((s,r)=>s+r[3],0);hero=money(payment(v.p,v.r,v.n));label='YOUR MONTHLY EMI';metrics=[['Total interest',money(interest)],['Total repayment',money(v.p+interest)],['Paid off in',schedule.length+' months'],['Interest saved',money(Math.max(0,baseline-interest))]];ratio=v.p/(v.p+interest)*100;note=v.x?'Includes '+money(v.x)+' extra each month. Final payment is adjusted.':'Fixed monthly payments. Final payment is adjusted to clear the balance.'}else if(mode===1){let a=payment(v.p,v.a,v.na),b=payment(v.p,v.b,v.nb),ta=a*v.na+v.fa,tb=b*v.nb+v.fb;hero=money(Math.abs(ta-tb));label='DIFFERENCE IN TOTAL COST';metrics=[['Loan A EMI',money(a)],['Loan B EMI',money(b)],['Loan A total + fee',money(ta)],['Loan B total + fee',money(tb)]];note=Math.abs(ta-tb)<.005?'Both loans have the same total cash outflow.':'Loan '+(ta<tb?'A':'B')+' has the lower total cash outflow. Fees are paid upfront.'}else if(mode===2){let i=v.p*v.r/100*v.n/12;hero=money((v.p+i)/v.n);label='FLAT-LOAN MONTHLY PAYMENT';metrics=[['Total interest',money(i)],['Total repayment',money(v.p+i)],['Interest-only monthly',money(i/v.n)],['Interest-only final payment',money(v.p+i/v.n)]];note='For interest-only loans, repay the principal with the final interest payment.'}else{let cut=v.d,fee=v.p*v.c/100,div=(cut-fee)/v.n;hero=money(v.p-cut);label='WINNER PAYOUT';metrics=[['Gross installment',money(v.p/v.n)],['Dividend per member',money(div)],['Net installment',money(v.p/v.n-div)],['Organizer commission',money(fee)]];note='Dividend pool: '+money(cut-fee)+'. This is one auction, not a full-cycle return.'}$('#error').textContent='';$('#hero').textContent=hero;$('#result-label').textContent=label;$('#metrics').innerHTML=metrics.map(([l,x])=>'<div class="metric"><span>'+l+'</span><strong>'+x+'</strong></div>').join('');$('#result-note').textContent=note;$('#chart').innerHTML=ratio===null?'':'<div class="bar"><span style="width:'+ratio+'%"></span></div><div class="legend"><span>Principal '+ratio.toFixed(1)+'%</span><span>Interest '+(100-ratio).toFixed(1)+'%</span></div>';$('#schedule').hidden=mode!==0;$('#rows').innerHTML=schedule.map(row=>'<tr>'+row.map((v,i)=>'<td>'+(i?money(v):v)+'</td>').join('')+'</tr>').join('');lastResult={calculator:configs[mode].name,label,value:hero,metrics,note};return lastResult}catch(e){$('#error').textContent=e.message;$('#hero').textContent='—';$('#metrics').innerHTML='';$('#chart').innerHTML='';$('#result-note').textContent='Correct the highlighted inputs and calculate again.';$('#schedule').hidden=true;lastResult={error:e.message};return lastResult}}
function select(i){mode=i;$('#planner').hidden=i!==4;$('#tabs').innerHTML=configs.map((c,j)=>'<button type="button" aria-pressed="'+(i===j)+'" class="'+(i===j?'active':'')+'" data-mode="'+j+'">'+c.name+'</button>').join('');$('#title').textContent=configs[i].name;$('#number').textContent='0'+(i+1);$('#intro').textContent=configs[i].intro;$('#fields').innerHTML=configs[i].fields.map(([k,l,v])=>'<label for="f-'+k+'">'+l+'<input id="f-'+k+'" name="'+k+'" type="number" min="0" step="any" required value="'+v+'"></label>').join('');if(i===4){setupPlanner();const old=$('#f-take');const picker=document.createElement('select');picker.id='f-take';picker.name='take';picker.innerHTML=Array.from({length:20},(_,j)=>'<option value="'+(j+1)+'">Month '+(j+1)+'</option>').join('');picker.value=old.value;old.replaceWith(picker);}calculate()}

const plannerBids=[1270000,1320000,1295000,1290000,1220000,1150000,1020000,910000,800000,755000,730000,685000,585000,505000,445000,380000,320000,260000,200000,0];
let plannerValues=null,plannerRows=[],plannerFace=4000000;
function plannerMath(v,bids){
 if(!Number.isFinite(v.p)||v.p<=0||!Number.isFinite(v.paid)||v.paid<0||!Number.isFinite(v.external)||v.external<0||!Number.isFinite(v.commission)||v.commission<0||v.commission>=100)throw Error('Use a positive face value, nonnegative contributions and interest, and commission below 100%.');
 if(v.p<10000||v.p>10000000)throw Error('Chit amount must be between ₹10,000 and ₹1 crore.');
 if(v.take!==undefined&&(!Number.isInteger(v.take)||v.take<1||v.take>20))throw Error('Choose a payout month from 1 to 20.');
 if(bids.length!==20)throw Error('Enter all 20 monthly bids.');
 const fee=v.p*v.commission/100;
 let rows=bids.map((bid,i)=>{if(!Number.isFinite(bid)||bid<0||bid>=v.p)throw Error('Month '+(i+1)+': bid must be between zero and less than the face value.');
 if(i<19&&bid<fee)throw Error('Month '+(i+1)+': bid must include at least '+money(fee)+' commission.');
 let received=v.p-(i===19?bid+fee:bid);if(received<=0)throw Error('Month 20: bid plus commission must be less than face value.');
 let chit=received-v.paid,extPct=v.external/12*(19-i),external=received*extPct/100,total=chit+external,totalPct=total/received*100;
 return {month:i+1,bid,received,paid:v.paid,interestPaid:Math.max(0,v.paid-received),chit,external,monthlyExternal:received*v.external/1200,recovered:received+external,extPct,total,totalPct,monthly:totalPct/20,annual:totalPct/20*12};});
 const sorted=[...rows].sort((a,b)=>b.totalPct-a.totalPct||a.month-b.month);sorted.forEach((r,i)=>r.rank=i>0&&Math.abs(r.totalPct-sorted[i-1].totalPct)<1e-10?sorted[i-1].rank:i+1);return rows;
}
function setupPlanner(){if(plannerValues)for(const [k,v]of Object.entries(plannerValues))$('#f-'+k).value=v;
 $('#planner-rows').innerHTML=plannerBids.map((v,i)=>'<tr id="pm-'+i+'"><th scope="row">'+(i+1)+'</th><td><input aria-label="Month '+(i+1)+' bid amount in rupees" type="number" min="0" step="any" value="'+v+'" data-bid="'+i+'"></td>'+Array.from({length:11},()=>'<td>—</td>').join('')+'</tr>').join('');
}
function calculatePlanner(){try{const face=Number($('#f-p').value);if(Number.isFinite(face)&&face>=10000&&face<=10000000&&face!==plannerFace){const ratio=face/plannerFace;document.querySelectorAll('[data-bid]').forEach(el=>{if(el.value.trim()&&Number.isFinite(Number(el.value)))el.value=(Number(el.value)*ratio).toFixed(2);});const paid=$('#f-paid');if(paid.value.trim()&&Number.isFinite(Number(paid.value)))paid.value=(Number(paid.value)*ratio).toFixed(2);plannerFace=face;}const v=read();plannerValues=v;const bids=Array.from(document.querySelectorAll('[data-bid]')).map(el=>el.value.trim()===''?NaN:Number(el.value));const rows=plannerMath(v,bids);plannerBids.splice(0,20,...bids);plannerRows=rows;$('#planner-export').disabled=false;const chosen=rows[v.take-1];const best=rows.find(r=>r.rank===1),cash=[...rows].sort((a,b)=>b.total-a.total)[0];
 for(const [i,r]of rows.entries()){const cells=$('#pm-'+i).querySelectorAll('td');[money(r.received),money(r.paid),money(r.interestPaid),money(r.external),r.extPct.toFixed(2)+'%',money(r.recovered),money(r.total),r.totalPct.toFixed(2)+'%',r.monthly.toFixed(2)+'%',r.annual.toFixed(2)+'%','Rank '+r.rank].forEach((x,j)=>cells[j+1].textContent=x);$('#pm-'+i).classList.toggle('best-month',r.rank===1);$('#pm-'+i).classList.toggle('selected-month',r.month===v.take);}
 $('#error').textContent='';$('#result-label').textContent='MONTH '+v.take+' · AMOUNT YOU TAKE OUT';$('#hero').textContent=money(chosen.received);$('#chart').innerHTML='';$('#metrics').innerHTML=[['Total paid over 20 months',money(chosen.paid)],['Interest / cost you paid',money(chosen.interestPaid)],['Outside interest per month',money(chosen.monthlyExternal)],['Outside interest earned ('+(20-v.take)+' months)',money(chosen.external)],['Principal + outside interest',money(chosen.recovered)],['Net gain / loss',money(chosen.total)],['Average monthly chit payment',money(v.paid/20)],['Your month’s rank','Rank '+chosen.rank]].map(([l,x])=>'<div class="metric"><span>'+l+'</span><strong>'+x+'</strong></div>').join('');$('#result-note').textContent='Interest earned assumes the entire payout is lent at the entered annual rate for '+(20-v.take)+' months, without compounding. Best net %: Month '+best.month+' ('+best.totalPct.toFixed(2)+'%). Highest net gain / smallest loss: Month '+cash.month+' ('+money(cash.total)+'). Ranking uses unrounded Total %, not the cash amount.';$('#schedule').hidden=true;lastResult={calculator:'Chit Planner',selectedMonth:v.take,selectedResult:chosen,bestMonth:best.month,highestCashMonth:cash.month,rows};return lastResult;
 }catch(e){plannerRows=[];$('#planner-export').disabled=true;$('#error').textContent=e.message;$('#hero').textContent='—';$('#metrics').innerHTML='';$('#chart').innerHTML='';$('#result-note').textContent='Correct the values to compare all 20 months.';$('#schedule').hidden=true;document.querySelectorAll('#planner-rows tr').forEach(tr=>{tr.classList.remove('best-month','selected-month');tr.querySelectorAll('td').forEach((td,i)=>{if(i)td.textContent='—';});});lastResult={error:e.message};return lastResult;}}
$('#planner-rows').addEventListener('input',()=>calculatePlanner());
$('#planner-export').onclick=()=>{if(!plannerRows.length)return;const keys=['month','bid','received','paid','interestPaid','external','extPct','recovered','total','totalPct','monthly','annual','rank'];let csv='Month,Bid Amount,Amount Received,Total Paid Over 20 Months,Interest Cost Paid,Outside Interest Earned,Outside Interest %,Principal Plus Outside Interest,Net Gain Loss,Net %,Monthly Net %,Annual Net %,Rank\n'+plannerRows.map(r=>keys.map(k=>['month','rank'].includes(k)?r[k]:r[k].toFixed(2)).join(',')).join('\n');let url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download='chit-20-month-comparison.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};

$('#tabs').onclick=e=>{const b=e.target.closest('[data-mode]');if(b)select(Number(b.dataset.mode))};$('#form').onsubmit=e=>{e.preventDefault();calculate()};$('#form').addEventListener('input',e=>{if(mode===4&&e.target.id==='f-p'){plannerRows=[];lastResult={error:'Amount change awaiting calculation'};document.querySelectorAll('#planner-rows tr').forEach(tr=>{tr.classList.remove('best-month','selected-month');tr.querySelectorAll('td').forEach((td,i)=>{if(i)td.textContent='—';});});$('#hero').textContent='—';$('#metrics').innerHTML='';$('#chart').innerHTML='';$('#result-note').textContent='Finish entering the amount, then leave the field to update the plan.';$('#error').textContent='';$('#planner-export').disabled=true;return;}calculate();});
$('#form').addEventListener('change',e=>{if(mode===4&&e.target.id==='f-p'){const raw=e.target.value.trim(),face=Number(raw);if(raw&&Number.isFinite(face)&&face>=10000&&face<=10000000){const ratio=face/plannerFace;document.querySelectorAll('[data-bid]').forEach(el=>{const x=Number(el.value);if(el.value.trim()&&Number.isFinite(x))el.value=(x*ratio).toFixed(2);});const paid=$('#f-paid');if(paid.value.trim()&&Number.isFinite(Number(paid.value)))paid.value=(Number(paid.value)*ratio).toFixed(2);plannerFace=face;}calculate();}else if(mode===4)calculate();});$('#export').onclick=()=>{if(!schedule.length)return;let csv='Month,Payment,Principal,Interest,Balance\n'+schedule.map(r=>r.map((v,i)=>i?v.toFixed(2):v).join(',')).join('\n');let url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download='repayment-schedule.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};select(0);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_calculator_result',description:'Read the currently displayed money calculator result.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Expected an empty object.');return lastResult}})).catch(()=>{})}catch(e){}}
